def _reject_duplicate_keys(pairs):
    """object_pairs_hook：保序构造 dict，发现重复键即抛 ValueError。"""
    out = {}
    for key, value in pairs:
        if key in out:
            raise ValueError("JSON 对象含重复键：%r" % key)
        out[key] = value
    return out


