    "weights", "bias", "stride", "padding", "x", "dy", "eps", "atol", "rtol",
]


def _check_convcheck_stride(value):
    """校验 convcheck 的 stride：正 int[2] 且至少一项大于 1（拒绝 bool）。

    整体或成员类型错抛 TypeError，长度错、成员非正或两项都不大于 1
    抛 ValueError；通过时返回 (SH, SW) tuple。
    """
    if not isinstance(value, list):
        raise TypeError(
            "stride 必须是 int[2] list，得到 %s" % type(value).__name__
        )
    if len(value) != 2:
        raise ValueError("stride 必须恰含 (SH, SW) 两个元素")
    for member_name, member in (("SH", value[0]), ("SW", value[1])):
        if isinstance(member, bool) or not isinstance(member, int):
            raise TypeError(
                "stride 的 %s 必须是 int（拒绝 bool），得到 %s"
                % (member_name, type(member).__name__)
            )
        if member <= 0:
            raise ValueError("stride 的 %s 必须为正整数" % member_name)
    if value[0] <= 1 and value[1] <= 1:
        raise ValueError("stride 至少一项必须大于 1")
    return (value[0], value[1])


def _check_convcheck_padding(value):
    """校验 convcheck 的 padding：非负 int[4] 且至少一项大于 0（拒绝 bool）。

    整体或成员类型错抛 TypeError，长度错、成员为负或四项都为 0
    抛 ValueError；通过时返回 (PT, PB, PL, PR) tuple。
    """
    if not isinstance(value, list):
        raise TypeError(
            "padding 必须是 int[4] list，得到 %s" % type(value).__name__
        )
    if len(value) != 4:
        raise ValueError("padding 必须恰含 (PT, PB, PL, PR) 四个元素")
    for member_name, member in (
        ("PT", value[0]), ("PB", value[1]), ("PL", value[2]),
        ("PR", value[3]),
    ):
        if isinstance(member, bool) or not isinstance(member, int):
            raise TypeError(
                "padding 的 %s 必须是 int（拒绝 bool），得到 %s"
                % (member_name, type(member).__name__)
            )
        if member < 0:
            raise ValueError("padding 的 %s 必须为非负整数" % member_name)
    if not any(member > 0 for member in value):
        raise ValueError("padding 至少一项必须大于 0")
    return (value[0], value[1], value[2], value[3])


def _load_convcheck_config(config_path):
    """读取并严格校验 convcheck 的 CONFIG。

    CONFIG 须为无重复键的 UTF-8 JSON 对象，键依次为 weights、bias、
    stride、padding、x、dy、eps、atol、rtol；stride/padding 在此校验
    并转为 tuple，四张量与三容差的校验分别交给 Conv2D 构造、
    forward/backward 与 check_gradients 完成。
    返回 (weights, bias, stride, padding, x, dy, eps, atol, rtol)。
    """
    with open(config_path, "rb") as f:
        raw = f.read()
    doc = json.loads(
        raw.decode("utf-8"), object_pairs_hook=_reject_duplicate_keys
    )
    if not isinstance(doc, dict):
        raise TypeError("CONFIG 顶层必须是 JSON 对象")
    if list(doc.keys()) != _CONVCHECK_CONFIG_KEYS:
        raise ValueError(
            "CONFIG 键必须依次为 weights、bias、stride、padding、x、dy、"
            "eps、atol、rtol"
        )

    stride = _check_convcheck_stride(doc["stride"])
    padding = _check_convcheck_padding(doc["padding"])
    return (
        doc["weights"], doc["bias"], stride, padding,
        doc["x"], doc["dy"], doc["eps"], doc["atol"], doc["rtol"],
    )


def _float_tensor(t, name):
    """把嵌套 list 张量的每个叶值转为有限 float，返回新 list。"""
    if isinstance(t, list):
        return [_float_tensor(v, name) for v in t]
    v = float(t)
    if not math.isfinite(v):
        raise ValueError("%s 含有非有限值（NaN/inf）" % name)
    return v


def _cmd_convcheck(config_path, output_path):
    """convcheck 子命令主体；配置/计算/写出失败返回 1，ok 假也返回 1。"""
    try:
        if os.path.abspath(config_path) == os.path.abspath(output_path):
            raise ValueError("CONFIG 与 OUTPUT 不能是同一路径")
        (weights, bias, stride, padding, x, dy, eps, atol, rtol
         ) = _load_convcheck_config(config_path)

        layer = Conv2D(
            weights, bias, stride=stride, padding=padding,
            dilation=1, groups=1,
        )
        forward_out = layer.forward(x)
        dx, dweights, dbias = layer.backward(dy)

        check_layer = Conv2D(
            weights, bias, stride=stride, padding=padding,
            dilation=1, groups=1,
        )
        ok, max_e, max_r = check_gradients(
            check_layer, x, dy, eps=eps, atol=atol, rtol=rtol
        )
        if not (
            isinstance(ok, bool)
            and isinstance(max_e, float)
            and isinstance(max_r, float)
            and math.isfinite(max_e)
            and math.isfinite(max_r)
        ):
            raise ValueError("梯度检查结果非法或含非有限值（NaN/inf）")

        artifact = {
            "forward": _float_tensor(forward_out, "forward"),
            "backward": {
                "dx": _float_tensor(dx, "dx"),
                "dweights": _float_tensor(dweights, "dweights"),
                "dbias": _float_tensor(dbias, "dbias"),
            },
            "check": {"ok": ok, "max_e": max_e, "max_r": max_r},
        }
        payload = (_dump_compact(artifact) + "\n").encode("utf-8")
        _atomic_write_output(output_path, payload)
    except (ValueError, TypeError, OSError):
        return 1
    return 0 if ok else 1

